3	/**
4	 * Free Minecraft servers — one per verified account, running as a Docker
5	 * container on the dedicated "freemc-host" VM behind itzg/mc-router (hostname
6	 * -based routing + auto-scale up/down on connect/idle — see FreeMinecraftServer
7	 * in prisma/schema.prisma for the full architecture note).
8	 *
9	 * KNOWN GAP: disk usage is NOT hard-quota-enforced yet (Docker's storage-opt
10	 * quota needs XFS+pquota, which this host's filesystem doesn't have). The RAM
11	 * cap (Docker --memory, a real hard ceiling) and the total-server-count cap are
12	 * the enforced safety controls for now; `free_minecraft_disk_mb` exists for a
13	 * future periodic `du`-based sweep, not wired to anything yet.
14	 */
15	import { revalidatePath } from "next/cache";
16	import { db } from "./db";
17	import { requireUser } from "./auth";
18	import { assertEmailVerified } from "./email-verification";
19	import { checkRateLimit } from "./rate-limit";
20	import { getSettingBool, getSettingInt, getSetting } from "./settings";
21	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
22	import type { SftpServer } from "./sftp";
23	import { validateRconCommand } from "./game-control";
24	import { schemaFor, validateConfig } from "./game-config";
25	import {
26	  getFreeServerStatus,
27	  getFreeServerPlayers,
28	  sendRcon,
29	  readServerProperties,
30	  writeServerProperties,
31	  liveRconCommandFor,
32	  FREEMC_GAME_TYPES,
33	  FREEMC_GAME_MODES,
34	  legacyPresetKeyFor,
35	  recreateGameTypeContainer,
36	  applyModeProperties,
37	} from "./free-minecraft-control";
38	import { getFreemcHostCapacity, wouldExceedFreemcCapacity } from "./freemc-capacity";
39	
40	type Result = { error?: string };
41	
42	/**
43	 * Translates one of the OLD flat FREEMC_PRESETS keys (still the only thing
44	 * the not-yet-migrated dashboard UI — components/customer/freemc/*.tsx,
45	 * components/customer/FreeMinecraftPanel.tsx — ever submits) into the new
46	 * two-axis (gameType, gameMode) shape. The 3 old mode-only keys collapse onto
47	 * vanilla+that mode (that's exactly what they always meant); every other key
48	 * is a game type, always paired with survival (the old flat scheme had no
49	 * concept of "preserve the current mode across a preset switch" — every
50	 * preset fully specified its own properties, so this reproduces that
51	 * behavior exactly rather than inventing a new one for legacy callers).
52	 * Returns null for anything unrecognized.
53	 */
54	function mapLegacyPresetKey(key: string): { gameType: string; gameMode: string } | null {
55	  if (key === "creative" || key === "hardcore" || key === "peaceful") return { gameType: "vanilla", gameMode: key };
56	  if (FREEMC_GAME_TYPES[key]) return { gameType: key, gameMode: "survival" };
57	  return null;
58	}
59	
60	const SUBDOMAIN_RE = /^[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?$/;
61	const RESERVED = new Set(["www", "api", "admin", "mc", "play", "test", "server", "router"]);
62	
63	/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
64	 *  not a customer VPS. Reused via the same withServerSsh every game/backup
65	 *  action already uses; this just points it at our own internal box instead. */
66	async function freemcHost(): Promise<SftpServer> {
67	  const host = await db.server.findFirst({
68	    where: { hostname: "freemc-host" },
69	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
70	  });
71	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
72	  return host;
73	}
