80	export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
81	  const user = await requireUser();
82	  const subdomain = String(formData.get("subdomain") ?? "");
83	
84	  // Prefer the new two-axis fields (the UI being built in parallel sends
85	  // these); fall back to the legacy flat `preset` field the current create
86	  // form (components/customer/FreeMinecraftPanel.tsx) still submits, so
87	  // account creation keeps working unbroken through the UI migration.
88	  // Defaults to gameType=vanilla, gameMode=survival either way.
89	  const gameTypeField = formData.get("gameType");
90	  const gameModeField = formData.get("gameMode");
91	  let gameType = "vanilla";
92	  let gameMode = "survival";
93	  if (typeof gameTypeField === "string" && FREEMC_GAME_TYPES[gameTypeField]) {
94	    gameType = gameTypeField;
95	    if (typeof gameModeField === "string" && FREEMC_GAME_MODES[gameModeField]) gameMode = gameModeField;
96	  } else {
97	    const mapped = mapLegacyPresetKey(String(formData.get("preset") ?? "vanilla"));
98	    if (mapped) ({ gameType, gameMode } = mapped);
99	  }
