302	export async function renameFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
303	  const user = await requireUser();
304	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
305	  if (!row) return { error: "You don't have a free server." };
306	
307	  const name = String(formData.get("name") ?? "").trim().slice(0, 40);
308	  if (!name) return { error: "Enter a name." };
309	
310	  // Cosmetic only — never touches the container, the subdomain, or mc-router.
311	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { name } });
312	  revalidatePath("/dashboard/free-minecraft");
313	  return {};
314	}
