316	/**
317	 * Changes the connect address. The container's own identity (containerName,
318	 * data volume) never changes — only its `mc-router.host` label does, and
319	 * labels are immutable on a running container, so this is a stop -> remove ->
320	 * recreate with the SAME name and data mount, just a new label. World data is
321	 * untouched throughout; there's a few seconds of downtime while it recreates.
322	 */
323	export async function changeFreeMinecraftSubdomain(_prev: unknown, formData: FormData): Promise<Result> {
324	  const user = await requireUser();
325	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
326	  if (!row) return { error: "You don't have a free server." };
327	
328	  const rl = checkRateLimit(`freemc:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
329	  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };
330	
331	  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
332	  if (!SUBDOMAIN_RE.test(sub) || RESERVED.has(sub)) {
333	    return { error: "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word." };
334	  }
335	  if (sub === row.subdomain) return {};
336	
337	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
338	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
339	  // Preserve whatever game type/mode was active — moving your connect
340	  // address shouldn't reset your world or plugins.
341	  const gameTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
342	  const gameType = FREEMC_GAME_TYPES[gameTypeKey];
343	  const gameMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;
344	
345	  try {
346	    await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: sub } });
347	  } catch {
348	    return { error: "That name is taken — try another." };
349	  }
350	
351	  try {
352	    const host = await freemcHost();
353	    // "moved": now running under the new subdomain. "reverted": the new
354	    // address failed to boot, so it's back under the OLD one — the DB's
355	    // subdomain field must match, or the dashboard would show a "connect at"
356	    // address nothing is actually listening on.
357	    const outcome = await withServerSsh(host, async (conn) => {
358	      const applied = await recreateGameTypeContainer(conn, {
359	        containerName: row.containerName,
360	        dataPath: `/opt/freemc/servers/${row.id}`,
361	        subdomain: sub,
362	        domain,
363	        ramMb,
364	        ownerId: user.id,
365	        gameType,
366	        gameTypeKey,
367	        gameMode,
368	      });
369	      if (applied.ok) return { landed: "moved" as const };
370	      console.error("[free-minecraft] subdomain recreate failed, rolling back:", applied.error);
371	      const rolledBack = await recreateGameTypeContainer(conn, {
372	        containerName: row.containerName,
373	        dataPath: `/opt/freemc/servers/${row.id}`,
374	        subdomain: row.subdomain,
375	        domain,
376	        ramMb,
